import copy
from taf.rfrl.utilities.robot.parallel_runner import run_parallel_in_robot
from taf.rfrl.bts.devices.du.logs_collecting.basic_logs import GnbLog, EnbLog
from taf.rfrl.bts.devices.du.logs_collecting.btslog_collector import GnbBtslogCollector, EnbBtslogCollector
from taf.rfrl.bts.operations import download_bts_configuration, verify_bts_is_up_and_on_air, \
    wait_until_bts_is_up_and_on_air
from taf.rfrl.bts.operations import perform_bts_commissioning
from taf.rfrl.bts.parallel.runner import run_parallel_on_all_btses


# Logs Collecting
# -------------------------------------------------------------------------

def setup_btslog_collector_for_all_btses():
    """
    Setup BTS log collector for all BTSes.
    """
    run_parallel_on_all_btses(
        gnb_function=GnbBtslogCollector().setup_btslog_collector,
        enb_function=EnbBtslogCollector().setup_btslog_collector)


def start_collecting_btslog_from_all_btsses():
    """
    Start collecting BTS logs from all BTSes.
    """
    run_parallel_on_all_btses(
        gnb_function=GnbBtslogCollector().start_collecting_btslog,
        enb_function=EnbBtslogCollector().start_collecting_btslog)


def stop_btslog_and_download_logs_from_all_btsses(log_dir):
    """
    Stop collecting BTS logs and download them from all BTSes.
    :param log_dir: Directory where the logs will be downloaded.
    :return: Dictionary with the results of the functions. eg:
    {
        'GNB0': '/log_dir/btslog_REST_GNB0_DU0_77012_77012/syslog_files.tgz',
        'GNB1': '/log_dir/btslog_REST_GNB1_DU0_77013_77013/syslog_files.tgz',
    }
    """
    function_kwargs = {'log_dir': log_dir}
    results = run_parallel_on_all_btses(
        gnb_function=GnbBtslogCollector().stop_collecting_btslog,
        enb_function=EnbBtslogCollector().stop_collecting_btslog,
        gnb_function_kwargs=function_kwargs,
        enb_function_kwargs=function_kwargs,)
    return results


def teardown_btslog_collector_for_all_btses():
    """
    Teardown BTS log collector for all BTSes.
    """
    run_parallel_on_all_btses(
        gnb_function=GnbBtslogCollector().teardown_btslog_collector,
        enb_function=EnbBtslogCollector().teardown_btslog_collector)

