def save_current_configuration_from_all_btsses(log_dir):
    """
    Save current configuration from all BTSes.
    :param log_dir: Directory where the logs will be downloaded.
    :return: Dictionary with the results of the functions. eg:
    {
        'GNB0':     {
            'BTS': '/log_dir/REST_GNB0_DU0_current_scf.xml',
            'ASIR': '/log_dir/REST_GNB0_ASIR_current_scf.xml',
    },
        'GNB1':     {
            'BTS': '/log_dir/REST_GNB1_DU0_current_scf.xml',
            'ASIR': '/log_dir/REST_GNB1_ASIR_current_scf.xml',
    },
    }
    """
    function_kwargs = {'log_dir': log_dir}
    gnb_function_kwargs = copy.deepcopy(function_kwargs)
    gnb_function_kwargs['bts_type'] = 'GNB'
    enb_function_kwargs = copy.deepcopy(function_kwargs)
    enb_function_kwargs['bts_type'] = 'ENB'

    results = run_parallel_on_all_btses(
        gnb_function=download_bts_configuration,
        enb_function=download_bts_configuration,
        gnb_function_kwargs=gnb_function_kwargs,
        enb_function_kwargs=enb_function_kwargs,)
    return results

# BTS checking
# -------------------------------------------------------------------------


def verify_all_btses_are_up_and_on_air():
    """
    Verify if all BTSes are up and on air.
    """
    run_parallel_on_all_btses(
        gnb_function=verify_bts_is_up_and_on_air,
        enb_function=verify_bts_is_up_and_on_air,
        gnb_function_kwargs={'bts_type': 'GNB'},
        enb_function_kwargs={'bts_type': 'ENB'},)


def wait_until_all_btses_are_up_and_on_air(timeout=300):
    """
    Wait until all BTSes are up and on air.
    """
    run_parallel_on_all_btses(
        gnb_function=wait_until_bts_is_up_and_on_air,
        enb_function=wait_until_bts_is_up_and_on_air,
        gnb_function_kwargs={'bts_type': 'GNB', 'timeout': timeout},
        enb_function_kwargs={'bts_type': 'ENB', 'timeout': timeout},)


def perform_commissioning_on_all_btses(prefix_tag=None, wait_for_on_air=True,
                                       force_reconnect=False, asir_commissioning=True, interface='lmp',
                                       commissioning_timeout=600, asir_commissioning_timeout=120,
                                       wait_for_on_air_timeout=300, delay_for_checking_on_air=30,
                                       skip_parameter_relation_errors=True, params_per_bts=None):
    """
    Perform full commissioning on all BTSes defined in configuration file. If you would like to perform commissioning
    only on selected BTSes or you would like to use different parameters per BTS,
    you can use the params_per_bts parameter as list of dictionaries:
    params_per_bts = [
        {
                # REQUIRED PARAMS
                'bts_id': 0,
                'bts_type': 'GNB',

                # OPTIONAL PARAMS
                'scf_path': 'scf_path',
                'asir_scf_path': 'asir_scf_path',
                'prefix_tag': 'prefix_tag',                     # applicable only when scf_path not provided
                'wait_for_on_air': True,
                'force_reconnect': False,
                'asir_commissioning': True,                     # only if ASIR is present
                'interface': lmp,                               # lmp/mplane
                'commissioning_timeout': 600,
                'asir_commissioning_timeout': 120,
                'wait_for_on_air_timeout': 300,
                'delay_for_checking_on_air': 30,
                'skip_parameter_relation_errors': True,
        },
        {
                'bts_id': 1,
                'bts_type': 'GNB',
                'scf_path': '/tmp/SCF.xml',
        },
        {
                'bts_id': 0,
                'bts_type': 'ENB',
                'prefix_tag': '8CC',
        },

    ]
    All available parameters tou can check under 'perform_bts_commissioning' function(taf.rfrl.bts.operations)

    If params_per_bts is not provided, the common function parameters(all except 'params_per_bts') will be
    applied to all BTSes.
    You don't need to pass all keys, only the ones you want to change. Rest will be taken from(merged with) the common
    function parameters.

    :param prefix_tag: Prefix tag for the commissioning for more details check:
                       https://confluence.ext.net.nokia.com/display/5GPzKRK/TL+Commissioning
    :param wait_for_on_air: Wait for the BTS to be on air.
    :param force_reconnect: Force reconnect.
    :param asir_commissioning: True/False - If True - perform ASIR commissioning if ASIR is present in configuration.
    :param interface: Interface to connect with BTS lmp/mplane
    :param commissioning_timeout: Time in seconds to wait for BTS commissioning process finishes
    :param asir_commissioning_timeout: Time in seconds to wait for ASIR commissioning process finishes
    :param wait_for_on_air_timeout: Time in seconds to wait for BTS to be on air
    :param delay_for_checking_on_air: Time in seconds to wait before checking OnAir
    :param skip_parameter_relation_errors: True/False - If True - skip parameter relation errors
                                           during BTS commissioning
    :param params_per_bts: List of parameters for each BTS - check perform_full_bts_commissioning for available params.
    """

    common_function_kwargs = {
        'prefix_tag': prefix_tag,
        'wait_for_on_air': wait_for_on_air,
        'force_reconnect': force_reconnect,
        'asir_commissioning': asir_commissioning,
        'interface': interface,
        'commissioning_timeout': commissioning_timeout,
        'asir_commissioning_timeout': asir_commissioning_timeout,
        'wait_for_on_air_timeout': wait_for_on_air_timeout,
        'delay_for_checking_on_air': delay_for_checking_on_air,
        'skip_parameter_relation_errors': skip_parameter_relation_errors,
    }
    if params_per_bts is None:
        run_parallel_on_all_btses(
            gnb_function=perform_bts_commissioning,
            enb_function=perform_bts_commissioning,
            gnb_function_kwargs={'bts_type': 'GNB'},
            enb_function_kwargs={'bts_type': 'ENB'})
    else:
        list_of_functions = []
        for params in params_per_bts:
            kwargs = copy.copy(common_function_kwargs)
            kwargs.update(params)
            list_of_functions.append({
                'function': perform_bts_commissioning,
                'function_kwargs': kwargs,
                'device_name': "{}{}".format(params['bts_type'], params['bts_id'])
            })
        run_parallel_in_robot(list_of_functions)
